<script lang="ts">
 import{onMount}from'svelte';import EChartsRenderer from '../../charts/EChartsRenderer.svelte';import{getV6RunDetail,getV6Runs,type V6RunDetail,type V6Runs,type V6RunSeed}from'../v6Api';const CAPITAL=60000000;let runsData=$state<V6Runs|null>(null);let detail=$state<V6RunDetail|null>(null);let selected=$state('');let error=$state<string|null>(null);let loading=$state(true);let detailLoading=$state(false);
 const key=(d:string|undefined,r:string|undefined)=>`${d??''}\u0000${r??''}`;const text=(v:unknown)=>v===undefined||v===null||v===''?'MISSING':String(v);const num=(v:unknown)=>typeof v==='number'&&Number.isFinite(v)?v:undefined;const won=(v:unknown)=>num(v)===undefined?'MISSING':`₩${new Intl.NumberFormat('ko-KR').format(num(v)!)}`;const color=(name:string)=>typeof document==='undefined'?'transparent':getComputedStyle(document.documentElement).getPropertyValue(name).trim();const seeds=()=>Object.entries(detail?.manifest?.per_seed??{}) as [string,V6RunSeed][];const rows=$derived([...seeds().map(([seed,v])=>({name:`policy seed ${seed}`,nav:num(v.final_val_metrics?.nav)})),...['no_trade','rule_topk_ret5','random_topk'].map(name=>({name,nav:num(detail?.manifest?.baselines?.[name]?.nav)}))].filter(x=>x.nav!==undefined));const chartOption=$derived({tooltip:{trigger:'axis',axisPointer:{type:'shadow'},valueFormatter:(v:number)=>won(v)},xAxis:{type:'value',axisLabel:{formatter:(v:number)=>won(v)}},yAxis:{type:'category',data:rows.map(x=>x.name)},series:[{type:'bar',data:rows.map(x=>({value:x.nav,itemStyle:{color:x.nav!>=CAPITAL?color('--success'):x.nav!>=CAPITAL*.95?color('--muted'):color('--danger')}})),markLine:{silent:true,data:[{xAxis:CAPITAL,label:{formatter:'60M'}}]}}]});
 async function selectRun(){const[d,r]=selected.split('\u0000');if(!d||!r)return;detailLoading=true;detail=null;const x=await getV6RunDetail(d,r);detailLoading=false;if(x.ok&&x.data)detail=x.data;else error=x.error??'알 수 없는 오류가 발생했습니다.'}async function load(){const x=await getV6Runs();loading=false;if(x.ok&&x.data){runsData=x.data;const run=x.data.runs?.[0];if(run){selected=key(run.dataset_run_id,run.run_id);selectRun()}}else error=x.error??'알 수 없는 오류가 발생했습니다.'}onMount(load);
</script>
{#if loading}<section class="panel">비교할 실행 기록을 확인하고 있습니다.</section>{:else if error&&!runsData}<section class="panel error">{error}</section>{:else if runsData}<section class="compare-page"><header><p class="eyebrow">RESEARCH COMPARISON</p><h1>비교</h1><p>같은 실행 manifest의 검증 결과만 비교합니다.</p></header>{#if !(runsData.runs?.length)}<section class="empty-state"><h2>비교할 실행이 없습니다</h2></section>{:else}<section class="card picker"><h2>실행 선택</h2>{#each runsData.runs??[] as run}<button class:chosen={selected===key(run.dataset_run_id,run.run_id)} onclick={()=>{selected=key(run.dataset_run_id,run.run_id);selectRun()}}>{text(run.dataset_run_id)} · {text(run.run_id)}</button>{/each}</section>{#if detailLoading}<section class="card">선택한 실행 manifest를 읽고 있습니다.</section>{:else if detail?.manifest}<section class="card wide"><h2>전략별 validation NAV</h2>{#if rows.length}<EChartsRenderer option={chartOption} height="320px" caption="전략별 validation NAV · 60M 기준선" />{:else}<p>표시할 데이터 없음 · NOT_RUN</p>{/if}</section><section class="card wide"><h2>수치 매트릭스</h2><div class="table-wrap"><table><thead><tr><th>지표</th>{#each seeds() as [seed]}<th>policy seed {seed}</th>{/each}<th>no_trade</th><th>rule_topk_ret5</th><th>random_topk</th></tr></thead><tbody><tr><th>val NAV</th>{#each seeds() as [,v]}<td>{won(v.final_val_metrics?.nav)}</td>{/each}{#each ['no_trade','rule_topk_ret5','random_topk'] as name}<td>{won(detail.manifest.baselines?.[name]?.nav)}</td>{/each}</tr></tbody></table></div></section><div class="grid"><section class="card blocked"><h2>KOSPI / KOSDAQ</h2><p>BLOCKED_INDEX_SERIES_SOURCE · KRX 자격증명 필요</p></section><section class="card"><h2>변형 검증</h2><p>H3 / H5 · NOT_RUN · 변형 검증 대기</p></section></div>{/if}{/if}</section>{/if}
<style>.compare-page,.panel{width:100%;border:1px solid var(--border);border-radius:14px;padding:clamp(18px,4vw,32px);background:var(--surface);color:var(--fg)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(420px,1fr));gap:16px;margin-top:16px}.card,.empty-state{margin-top:16px;border:1px solid var(--border-strong);border-radius:10px;padding:16px;background:var(--surface-raised)}.wide{grid-column:1/-1}.eyebrow{color:var(--accent);font-size:.82rem;font-weight:800;letter-spacing:.1em}h1,h2{color:var(--fg-strong)}h1{font-size:clamp(1.8rem,6vw,2.6rem)}h2{font-size:1.15rem}.picker button{display:block;width:100%;margin:6px 0;border:1px solid var(--border-strong);border-radius:6px;padding:8px;background:var(--surface-sunken);color:var(--fg);font:inherit;text-align:left}.picker .chosen{border-color:var(--accent)}.blocked{border-color:var(--danger);background:var(--danger-soft);color:var(--danger)}.table-wrap{overflow-x:auto}table{width:100%;min-width:720px;border-collapse:collapse;font-size:.85rem}th,td{border-top:1px solid var(--border);padding:8px;text-align:left}th{color:var(--muted)}.error{color:var(--danger)}</style>